fn shout(s: Str) -> Str {
  return str_upper(s) + "!";
}

fn whisper(s: Str) -> Str {
  return str_lower(s) + "...";
}

fn match_command(input: Str, expected: Str) -> Bool {
  return str_lower(input) == str_lower(expected);
}

fn main() -> Int {
  if match_command("QUIT", "quit") { return 1; }
  return 0;
}
